use std::f64::consts::{PI, SQRT_2};

/// The standard normal quantile `qnorm(p)`.
pub fn qnorm_std(p: f64) -> f64 {
    if p.is_nan() {
        return p;
    }
    if p == 0.0 {
        return f64::NEG_INFINITY;
    }
    if p == 1.0 {
        return f64::INFINITY;
    }
    if !(0.0..=1.0).contains(&p) {
        return f64::NAN;
    }

    let q = p - 0.5;
    if q.abs() <= 0.425 {
        let r = 0.180625 - q * q;
        return q
            * (((((((r * 2509.0809287301226727 + 33430.575583588128105) * r
                + 67265.770927008700853)
                * r
                + 45921.953931549871457)
                * r
                + 13731.693765509461125)
                * r
                + 1971.5909503065514427)
                * r
                + 133.14166789178437745)
                * r
                + 3.387132872796366608)
            / (((((((r * 5226.495278852854561 + 28729.085735721942674) * r
                + 39307.89580009271061)
                * r
                + 21213.794301586595867)
                * r
                + 5394.1960214247511077)
                * r
                + 687.1870074920579083)
                * r
                + 42.313330701600911252)
                * r
                + 1.);
    }

    // r = sqrt(-log(min(p, 1 - p))); 1 - p is written as R's R_DT_CIv.
    let lp = (if q > 0.0 { 0.5 - p + 0.5 } else { p }).ln();
    let mut r = (-lp).sqrt();
    let mut val;
    if r <= 5. {
        r += -1.6;
        val = (((((((r * 7.7454501427834140764e-4 + 0.0227238449892691845833) * r
            + 0.24178072517745061177)
            * r
            + 1.27045825245236838258)
            * r
            + 3.64784832476320460504)
            * r
            + 5.7694972214606914055)
            * r
            + 4.6303378461565452959)
            * r
            + 1.42343711074968357734)
            / (((((((r * 1.05075007164441684324e-9 + 5.475938084995344946e-4) * r
                + 0.0151986665636164571966)
                * r
                + 0.14810397642748007459)
                * r
                + 0.68976733498510000455)
                * r
                + 1.6763848301838038494)
                * r
                + 2.05319162663775882187)
                * r
                + 1.);
    } else if r <= 27. {
        r += -5.;
        val = (((((((r * 2.01033439929228813265e-7 + 2.71155556874348757815e-5) * r
            + 0.0012426609473880784386)
            * r
            + 0.026532189526576123093)
            * r
            + 0.29656057182850489123)
            * r
            + 1.7848265399172913358)
            * r
            + 5.4637849111641143699)
            * r
            + 6.6579046435011037772)
            / (((((((r * 2.04426310338993978564e-15 + 1.4215117583164458887e-7) * r
                + 1.8463183175100546818e-5)
                * r
                + 7.868691311456132591e-4)
                * r
                + 0.0148753612908506148525)
                * r
                + 0.13692988092273580531)
                * r
                + 0.59983220655588793769)
                * r
                + 1.);
    } else if r >= 6.4e8 {
        val = r * SQRT_2;
    } else {
        let two_pi = 2.0 * PI;
        let s2 = -2.0 * lp;
        let mut x2 = s2 - (two_pi * s2).ln();
        if r < 36000. {
            x2 = s2 - (two_pi * x2).ln() - 2. / (2. + x2);
            if r < 840. {
                x2 = s2 - (two_pi * x2).ln() + 2. * (-(1. - 1. / (4. + x2)) / (2. + x2)).ln_1p();
                if r < 109. {
                    x2 = s2 - (two_pi * x2).ln()
                        + 2. * (-(1. - (1. - 5. / (6. + x2)) / (4. + x2)) / (2. + x2)).ln_1p();
                    if r < 55. {
                        x2 = s2 - (two_pi * x2).ln()
                            + 2. * (-(1. - (1. - (5. - 9. / (8. + x2)) / (6. + x2)) / (4. + x2))
                                / (2. + x2))
                                .ln_1p();
                    }
                }
            }
        }
        val = x2.sqrt();
    }
    if q < 0.0 {
        val = -val;
    }
    val
}
